"""ISO 27001:2022 control catalog — Annex A (93 controls) + ISMS clauses 4-10 (23).

Titles are locked to docs/iso-iec-27001-2022.pdf via iso_27001_official.py
(`official_title`). Summaries remain paraphrased implementation guidance,
not the copyrighted shall-text of the standard.
"""

CLAUSE_CONTROLS = [
    {"id": "4.1", "section": "Clauses", "title": "Understanding the organization and its context", "summary": "Identify internal and external factors that influence the organization’s ability to achieve information security objectives, ensuring the ISMS is aligned with its context.", "doc_link": "isms_policy.md"},
    {"id": "4.2", "section": "Clauses", "title": "Understanding the needs and expectations of interested parties", "summary": "Analyze the needs and expectations of interested parties to incorporate them into the ISMS and address relevant information security requirements.", "doc_link": "isms_policy.md"},
    {"id": "4.3", "section": "Clauses", "title": "Determining the scope of the information security management system", "summary": "Define the scope of the ISMS by considering internal and external factors, stakeholder needs, and dependencies within the operational environment.", "doc_link": "isms_policy.md"},
    {"id": "4.4", "section": "Clauses", "title": "Information security management system", "summary": "Build, run, and continually improve an ISMS to effectively manage information security risks and meet organizational goals.", "doc_link": "isms_policy.md"},
    {"id": "5.1", "section": "Clauses", "title": "Leadership and commitment", "summary": "Demonstrate leadership and commitment by supporting the ISMS, aligning it with organizational objectives, allocating resources, promoting a security culture, and driving continual improvement.", "doc_link": "isms_policy.md"},
    {"id": "5.2", "section": "Clauses", "title": "Policy", "summary": "Establish an information security policy aligned with the organization's objectives and strategic direction, outlining commitments to compliance, continual improvement, and the promotion of information security.", "doc_link": "information_security_policy.md"},
    {"id": "5.3", "section": "Clauses", "title": "Organizational roles, responsibilities and authorities", "summary": "Define, assign, and communicate roles, responsibilities, and authorities to ensure the effective implementation and operation of the ISMS, with accountability aligned to organizational objectives.", "doc_link": "roles_and_responsibilities_policy.md"},
    {"id": "6.1", "section": "Clauses", "title": "Actions to address risks and opportunities", "summary": "Consider internal and external issues and interested-party requirements to determine the risks and opportunities that need to be addressed, and plan actions — integrated into ISMS processes and evaluated for effectiveness — to achieve intended outcomes, prevent undesired effects, and support continual improvement.", "doc_link": "risk_assessment_policy.md"},
    {"id": "6.2", "section": "Clauses", "title": "Information security objectives and planning to achieve them", "summary": "Set measurable information security objectives aligned with the ISMS and strategic goals, and plan actions detailing responsibilities, resources, timelines, and evaluation methods to achieve them.", "doc_link": "isms_policy.md"},
    {"id": "6.3", "section": "Clauses", "title": "Planning of changes", "summary": "Plan changes to the ISMS systematically to ensure alignment with information security requirements, seamless integration into existing processes, and effective risk management.", "doc_link": "—"},
    {"id": "7.1", "section": "Clauses", "title": "Resources", "summary": "Provide the necessary resources to build, run, and continually improve the ISMS, ensuring its effective operation and alignment with organizational goals.", "doc_link": "isms_policy.md"},
    {"id": "7.2", "section": "Clauses", "title": "Competence", "summary": "Ensure personnel involved in the ISMS possess the necessary competence through appropriate education, training, or experience to fulfill their responsibilities effectively.", "doc_link": "human_resource_security_policy.md"},
    {"id": "7.3", "section": "Clauses", "title": "Awareness", "summary": "Promote awareness among relevant personnel about the ISMS, their role in information security, and the importance of compliance with security policies and requirements.", "doc_link": "employee_training_procedure.md"},
    {"id": "7.4", "section": "Clauses", "title": "Communication", "summary": "Establish effective internal and external communication processes, ensuring the timely and appropriate exchange of information relevant to the ISMS and its objectives.", "doc_link": "isms_policy.md"},
    {"id": "7.5", "section": "Clauses", "title": "Documented information", "summary": "Ensure the ISMS includes documented information required by the standard and determined as necessary for its effectiveness, with controls for creating, updating and governing it, including distribution, access, retrieval, use, storage, protection, retention and disposition.", "doc_link": "isms_policy.md"},
    {"id": "8.1", "section": "Clauses", "title": "Operational planning and control", "summary": "Plan and control ISMS processes, ensuring consistency with requirements and making necessary adjustments to address risks and opportunities.", "doc_link": "isms_policy.md"},
    {"id": "8.2", "section": "Clauses", "title": "Information security risk assessment", "summary": "Implement the risk assessment process to identify, evaluate, and prioritize information security risks as defined in the ISMS framework.", "doc_link": "risk_assessment_procedure.md"},
    {"id": "8.3", "section": "Clauses", "title": "Information security risk treatment", "summary": "Apply the risk treatment process by selecting and implementing appropriate controls to address identified risks, ensuring alignment with the organization’s risk acceptance criteria.", "doc_link": "risk_assessment_framework.md"},
    {"id": "9.1", "section": "Clauses", "title": "Monitoring, measurement, analysis and evaluation", "summary": "Monitor, measure, analyze, and evaluate the ISMS’s performance and effectiveness using appropriate methods aligned with the organization’s objectives.", "doc_link": "audit_policy.md"},
    {"id": "9.2", "section": "Clauses", "title": "Internal audit", "summary": "Conduct internal audits at planned intervals to provide information on whether the ISMS conforms to the organization's own requirements and the requirements of the standard, and is effectively implemented and maintained.", "doc_link": "audit_policy.md"},
    {"id": "9.3", "section": "Clauses", "title": "Management review", "summary": "Ensure top management reviews the ISMS at planned intervals to confirm its continuing suitability, adequacy and effectiveness, based on defined inputs including the status of previous actions, changes in internal and external issues and interested-party needs, and feedback on information security performance.", "doc_link": "management_review_template.md"},
    {"id": "10.1", "section": "Clauses", "title": "Continual improvement", "summary": "Identify and act on opportunities for continual improvement to enhance the ISMS's effectiveness and alignment with organizational goals.", "doc_link": "isms_policy.md"},
    {"id": "10.2", "section": "Clauses", "title": "Nonconformity and corrective action", "summary": "Address nonconformities by taking corrective actions, identifying root causes, and implementing measures to prevent recurrence while documenting the process.", "doc_link": "actions_register.md"},
]

ANNEX_A_CONTROLS = [
    {"id": "A.5.1", "section": "A.5 Organizational", "title": "Policies for information security", "summary": "Ensure information security policies and topic-specific policies are defined, approved by management, published, communicated and acknowledged by relevant personnel and interested parties, and reviewed at planned intervals and when significant changes occur, to keep management direction effective and aligned with business, legal, statutory, regulatory and contractual requirements.", "doc_link": "information_security_policy.md"},
    {"id": "A.5.2", "section": "A.5 Organizational", "title": "Information security roles and responsibilities", "summary": "This control defines and assigns roles and responsibilities for information security to ensure accountability. Measures include clear documentation of responsibilities, periodic reviews, and enforcement mechanisms.", "doc_link": "roles_and_responsibilities_policy.md"},
    {"id": "A.5.3", "section": "A.5 Organizational", "title": "Segregation of duties", "summary": "Ensure conflicting duties and areas of responsibility are segregated to reduce the risk of fraud, error, and bypassing of information security controls. Measures include role separation, access restrictions, and regular audits.", "doc_link": "roles_and_responsibilities_policy.md"},
    {"id": "A.5.4", "section": "A.5 Organizational", "title": "Management responsibilities", "summary": "Ensure management understands its information security role and requires all personnel to apply information security in accordance with the established information security policy, topic-specific policies and procedures, so that all personnel are aware of and fulfil their information security responsibilities.", "doc_link": "roles_and_responsibilities_policy.md"},
    {"id": "A.5.5", "section": "A.5 Organizational", "title": "Contact with authorities", "summary": "Establish and maintain contact with relevant legal, regulatory and supervisory authorities to ensure an appropriate flow of information security-related communication between the organization and those authorities. Measures include maintaining updated contact lists and assigning responsibilities.", "doc_link": "isms_policy.md"},
    {"id": "A.5.6", "section": "A.5 Organizational", "title": "Contact with special interest groups", "summary": "This control facilitates contact with special interest groups to stay informed about security trends and practices. Measures include participation in forums, memberships, and collaborative initiatives.", "doc_link": "isms_policy.md"},
    {"id": "A.5.7", "section": "A.5 Organizational", "title": "Threat intelligence", "summary": "This control ensures threat intelligence is developed and maintained to identify and mitigate security risks. Measures include monitoring threat feeds, analyzing trends, and sharing actionable insights.", "doc_link": "risk_assessment_framework.md"},
    {"id": "A.5.8", "section": "A.5 Organizational", "title": "Information security in project management", "summary": "This control incorporates information security into project management practices. Measures include risk assessments, compliance reviews, and security checkpoints during project lifecycles.", "doc_link": "—"},
    {"id": "A.5.9", "section": "A.5 Organizational", "title": "Inventory of information and other associated assets", "summary": "Ensure an inventory of information and other associated assets, including their owners, is developed and maintained so their information security can be preserved and appropriate ownership assigned. Measures include asset tracking and periodic audits.", "doc_link": "asset_management_policy.md"},
    {"id": "A.5.10", "section": "A.5 Organizational", "title": "Acceptable use of information and other associated assets", "summary": "This control defines acceptable use of information and associated assets to ensure proper handling. Measures include documented policies, user training, and enforcement mechanisms.", "doc_link": "acceptable_use_policy.md"},
    {"id": "A.5.11", "section": "A.5 Organizational", "title": "Return of assets", "summary": "This control ensures the secure return of assets when employees or contractors leave or change roles. Measures include checklists, asset tracking, and decommissioning protocols.", "doc_link": "human_resource_security_policy.md"},
    {"id": "A.5.12", "section": "A.5 Organizational", "title": "Classification of information", "summary": "This control ensures information is classified based on its sensitivity and value to ensure appropriate protection. Measures include classification schemes, access restrictions, and labeling guidelines.", "doc_link": "data_classification_policy.md"},
    {"id": "A.5.13", "section": "A.5 Organizational", "title": "Labelling of information", "summary": "This control ensures consistent labeling of information to reflect its classification and handling requirements. Measures include standardized templates, training, and audits.", "doc_link": "data_classification_policy.md"},
    {"id": "A.5.14", "section": "A.5 Organizational", "title": "Information transfer", "summary": "This control establishes secure processes for transferring information between systems or organizations. Measures include encryption, access controls, and secure transfer protocols.", "doc_link": "communication_security_policy.md"},
    {"id": "A.5.15", "section": "A.5 Organizational", "title": "Access control", "summary": "This control implements and maintains access control mechanisms to restrict access to authorized individuals. Measures include role-based access, multi-factor authentication, and periodic reviews.", "doc_link": "access_control_policy.md"},
    {"id": "A.5.16", "section": "A.5 Organizational", "title": "Identity management", "summary": "This control ensures identities are managed securely to guarantee accurate and reliable access to systems. Measures include identity verification, lifecycle management, and access provisioning.", "doc_link": "access_control_policy.md"},
    {"id": "A.5.17", "section": "A.5 Organizational", "title": "Authentication information", "summary": "Ensure the allocation and management of authentication information follows a controlled process, including advising personnel on appropriate handling, so that entities are reliably authenticated and failures of authentication processes are prevented.", "doc_link": "access_control_policy.md"},
    {"id": "A.5.18", "section": "A.5 Organizational", "title": "Access rights", "summary": "This control ensures access rights are regularly reviewed and managed to align with roles and responsibilities. Measures include periodic audits, access revocation, and automated access management.", "doc_link": "access_control_policy.md"},
    {"id": "A.5.19", "section": "A.5 Organizational", "title": "Information security in supplier relationships", "summary": "This control ensures information security is embedded in supplier relationships and processes. Measures include due diligence, security reviews, and ongoing monitoring.", "doc_link": "supplier_security_policy.md"},
    {"id": "A.5.20", "section": "A.5 Organizational", "title": "Addressing information security within supplier agreements", "summary": "This control addresses information security requirements within supplier agreements. Measures include explicit contract clauses, compliance audits, and defined penalties for violations.", "doc_link": "supplier_security_policy.md"},
    {"id": "A.5.21", "section": "A.5 Organizational", "title": "Managing information security in the information and communication technology (ICT) supply chain", "summary": "This control manages information security risks in the ICT supply chain to ensure security of services and components. Measures include risk assessments, supplier evaluations, and incident response protocols.", "doc_link": "supplier_security_policy.md"},
    {"id": "A.5.22", "section": "A.5 Organizational", "title": "Monitoring, review and change management of supplier services", "summary": "This control ensures supplier services are monitored, reviewed, and adjusted to maintain information security. Measures include service level agreements, periodic reviews, and contract updates.", "doc_link": "supplier_security_policy.md"},
    {"id": "A.5.23", "section": "A.5 Organizational", "title": "Information security for use of cloud services", "summary": "This control ensures the secure use of cloud services by addressing associated risks. Measures include data encryption, access controls, and provider compliance reviews.", "doc_link": "cloud_security_policy.md"},
    {"id": "A.5.24", "section": "A.5 Organizational", "title": "Information security incident management planning and preparation", "summary": "This control ensures proper planning and preparation for managing information security incidents. Measures include incident response plans, training exercises, and communication protocols.", "doc_link": "incident_management_policy.md"},
    {"id": "A.5.25", "section": "A.5 Organizational", "title": "Assessment and decision on information security events", "summary": "Ensure information security events are assessed and categorized, so that events constituting information security incidents are identified and prioritized for appropriate handling.", "doc_link": "incident_response_plan.md"},
    {"id": "A.5.26", "section": "A.5 Organizational", "title": "Response to information security incidents", "summary": "This control ensures effective response to information security incidents to minimize impact and recover quickly. Measures include incident reporting, escalation protocols, and containment strategies.", "doc_link": "incident_response_plan.md"},
    {"id": "A.5.27", "section": "A.5 Organizational", "title": "Learning from information security incidents", "summary": "This control ensures lessons learned from information security incidents are documented and implemented to improve processes. Measures include post-incident reviews, action plans, and policy updates.", "doc_link": "incident_response_plan.md"},
    {"id": "A.5.28", "section": "A.5 Organizational", "title": "Collection of evidence", "summary": "This control ensures evidence is collected and preserved during security incidents to support investigations. Measures include chain-of-custody procedures, secure storage, and access controls.", "doc_link": "incident_response_plan.md"},
    {"id": "A.5.29", "section": "A.5 Organizational", "title": "Information security during disruption", "summary": "This control ensures information security is maintained during disruptions to guarantee continuity of operations. Measures include contingency plans, backup systems, and failover mechanisms.", "doc_link": "business_continuity_policy.md"},
    {"id": "A.5.30", "section": "A.5 Organizational", "title": "ICT readiness for business continuity", "summary": "This control ensures ICT readiness for business continuity to minimize downtime during disruptions. Measures include testing recovery plans, redundant systems, and disaster recovery sites.", "doc_link": "business_continuity_plan.md"},
    {"id": "A.5.31", "section": "A.5 Organizational", "title": "Legal, statutory, regulatory and contractual requirements", "summary": "This control ensures compliance with legal, statutory, regulatory, and contractual information security requirements. Measures include policy reviews, audits, and evidence documentation.", "doc_link": "compliance_policy.md"},
    {"id": "A.5.32", "section": "A.5 Organizational", "title": "Intellectual property rights", "summary": "Ensure compliance with legal, statutory, regulatory and contractual requirements related to intellectual property rights and the use of proprietary products. Measures include licensing reviews and legal agreements.", "doc_link": "compliance_policy.md"},
    {"id": "A.5.33", "section": "A.5 Organizational", "title": "Protection of records", "summary": "Ensure records are protected from loss, destruction, falsification, unauthorized access and unauthorized release, to meet legal, statutory, regulatory and contractual requirements as well as societal expectations for the protection and availability of records.", "doc_link": "data_retention_disposal_policy.md"},
    {"id": "A.5.34", "section": "A.5 Organizational", "title": "Privacy and protection of personal identifiable information (PII)", "summary": "This control protects privacy and ensures the secure handling of personally identifiable information (PII). Measures include anonymization, encryption, and compliance with privacy laws.", "doc_link": "data_protection_policy.md"},
    {"id": "A.5.35", "section": "A.5 Organizational", "title": "Independent review of information security", "summary": "This control ensures independent reviews of information security to evaluate effectiveness and compliance. Measures include external audits, risk assessments, and follow-up actions.", "doc_link": "audit_policy.md"},
    {"id": "A.5.36", "section": "A.5 Organizational", "title": "Compliance with policies, rules and standards for information security", "summary": "This control ensures compliance with all policies, rules, and standards for information security. Measures include regular training, policy reviews, and enforcement mechanisms.", "doc_link": "compliance_policy.md"},
    {"id": "A.5.37", "section": "A.5 Organizational", "title": "Documented operating procedures", "summary": "This control develops and maintains documented operating procedures to ensure consistency in security practices. Measures include process documentation, version control, and accessibility.", "doc_link": "procedures/"},
    {"id": "A.6.1", "section": "A.6 People", "title": "Screening", "summary": "Ensure background verification checks are carried out on all candidates before joining and on an ongoing basis, so that personnel are eligible and suitable for their roles throughout their employment, proportional to business requirements, the classification of information accessed and perceived risks.", "doc_link": "human_resource_security_policy.md"},
    {"id": "A.6.2", "section": "A.6 People", "title": "Terms and conditions of employment", "summary": "This control ensures that terms and conditions of employment include information security responsibilities. Measures include explicit clauses about confidentiality, compliance with policies, and consequences for breaches.", "doc_link": "human_resource_security_policy.md"},
    {"id": "A.6.3", "section": "A.6 People", "title": "Information security awareness, education and training", "summary": "This control ensures that employees receive regular information security awareness, education, and training. Measures include scheduled training sessions, e-learning programs, and simulated phishing exercises.", "doc_link": "employee_training_procedure.md"},
    {"id": "A.6.4", "section": "A.6 People", "title": "Disciplinary process", "summary": "This control establishes a disciplinary process to address breaches of information security policies. Measures include clear guidelines, escalation procedures, and consistent enforcement to maintain accountability.", "doc_link": "human_resource_security_policy.md"},
    {"id": "A.6.5", "section": "A.6 People", "title": "Responsibilities after termination or change of employment", "summary": "This control ensures that responsibilities related to information security are defined and enforced after termination or role changes. Measures include revoking access rights, collecting organizational assets, and conducting exit interviews.", "doc_link": "human_resource_security_policy.md"},
    {"id": "A.6.6", "section": "A.6 People", "title": "Confidentiality or non-disclosure agreements", "summary": "This control implements confidentiality or non-disclosure agreements to protect sensitive information. Measures include signed agreements at the start of employment, periodic reminders, and enforcement of legal actions in case of violations.", "doc_link": "confidentiality_agreement_template.md"},
    {"id": "A.6.7", "section": "A.6 People", "title": "Remote working", "summary": "This control ensures the secure management of information security risks during remote working. Measures include secure access to corporate systems, mandatory use of VPNs, and policies for handling sensitive data remotely.", "doc_link": "mobile_device_policy.md"},
    {"id": "A.6.8", "section": "A.6 People", "title": "Information security event reporting", "summary": "This control ensures employees can promptly report information security events. Measures include incident reporting channels, awareness campaigns, and follow-up procedures to investigate and address reported events.", "doc_link": "incident_management_policy.md"},
    {"id": "A.7.1", "section": "A.7 Physical", "title": "Physical security perimeters", "summary": "This control establishes physical security perimeters to protect critical areas from unauthorized access. Measures include barriers, access controls, and monitoring systems to ensure only authorized individuals can enter.", "doc_link": "physical_and_environmental_security_policy.md"},
    {"id": "A.7.2", "section": "A.7 Physical", "title": "Physical entry", "summary": "This control ensures physical entry points are controlled and monitored to prevent unauthorized access. Measures include badge systems, security personnel, and visitor logs.", "doc_link": "physical_and_environmental_security_policy.md"},
    {"id": "A.7.3", "section": "A.7 Physical", "title": "Securing offices, rooms and facilities", "summary": "This control ensures that offices, rooms, and facilities are secured to protect information and resources. Measures include locked doors, restricted areas, and surveillance systems.", "doc_link": "physical_and_environmental_security_policy.md"},
    {"id": "A.7.4", "section": "A.7 Physical", "title": "Physical security monitoring", "summary": "This control implements physical security monitoring to detect and respond promptly to threats. Measures include CCTV systems, motion detectors, and real-time alerts.", "doc_link": "physical_and_environmental_security_policy.md"},
    {"id": "A.7.5", "section": "A.7 Physical", "title": "Protecting against physical and environmental threats", "summary": "This control protects systems and resources from physical and environmental threats. Measures include fire suppression systems, temperature controls, and flood prevention barriers.", "doc_link": "physical_and_environmental_security_policy.md"},
    {"id": "A.7.6", "section": "A.7 Physical", "title": "Working in secure areas", "summary": "This control ensures that secure areas are managed to allow authorized access only. Measures include access control systems, visitor escorts, and activity monitoring.", "doc_link": "physical_and_environmental_security_policy.md"},
    {"id": "A.7.7", "section": "A.7 Physical", "title": "Clear desk and clear screen", "summary": "This control ensures sensitive information is not left exposed by adopting clear desk and clear screen policies. Measures include locking sensitive documents away and auto-locking screens when not in use.", "doc_link": "clear_desk_policy.md"},
    {"id": "A.7.8", "section": "A.7 Physical", "title": "Equipment siting and protection", "summary": "This control ensures that equipment is positioned and protected to prevent unauthorized access or damage. Measures include secure mounting, locked cabinets, and restricted access areas.", "doc_link": "physical_and_environmental_security_policy.md"},
    {"id": "A.7.9", "section": "A.7 Physical", "title": "Security of assets off-premises", "summary": "This control ensures assets used or stored off-premises are secured to maintain confidentiality and integrity. Measures include encryption, secure transport, and access tracking.", "doc_link": "mobile_device_policy.md"},
    {"id": "A.7.10", "section": "A.7 Physical", "title": "Storage media", "summary": "This control safeguards storage media to prevent unauthorized access or tampering. Measures include secure storage, encryption, and access restrictions.", "doc_link": "data_retention_disposal_policy.md"},
    {"id": "A.7.11", "section": "A.7 Physical", "title": "Supporting utilities", "summary": "This control ensures that supporting utilities, such as power and cooling systems, are reliable and protected from disruptions. Measures include redundant systems and physical security.", "doc_link": "—"},
    {"id": "A.7.12", "section": "A.7 Physical", "title": "Cabling security", "summary": "This control ensures that cables are secured to prevent unauthorized interception or damage. Measures include protective conduits, proper labeling, and secure routing.", "doc_link": "—"},
    {"id": "A.7.13", "section": "A.7 Physical", "title": "Equipment maintenance", "summary": "This control ensures that equipment is maintained to guarantee proper functioning and prevent failures. Measures include regular servicing, secure maintenance practices, and authorized personnel access.", "doc_link": "—"},
    {"id": "A.7.14", "section": "A.7 Physical", "title": "Secure disposal or re-use of equipment", "summary": "This control ensures the secure disposal or reuse of equipment to protect sensitive information. Measures include data sanitization, physical destruction, and certified disposal processes.", "doc_link": "disposal_destruction_policy.md"},
    {"id": "A.8.1", "section": "A.8 Technological", "title": "User endpoint devices", "summary": "This control ensures the protection of endpoint devices such as laptops, desktops, and mobile devices by implementing security measures like endpoint detection, encryption, and secure configurations to minimize risks.", "doc_link": "mobile_device_policy.md"},
    {"id": "A.8.2", "section": "A.8 Technological", "title": "Privileged access rights", "summary": "This control ensures that privileged access rights are granted, managed, and monitored carefully to prevent misuse and enhance security. Measures include role-based access controls, periodic reviews, and strict account management.", "doc_link": "access_control_policy.md"},
    {"id": "A.8.3", "section": "A.8 Technological", "title": "Information access restriction", "summary": "This control restricts access to sensitive information based on need-to-know principles. Measures include user authentication, role-based permissions, and regular access reviews.", "doc_link": "access_control_policy.md"},
    {"id": "A.8.4", "section": "A.8 Technological", "title": "Access to source code", "summary": "This control secures access to source code by preventing unauthorized viewing, modification, or exposure. Measures include version control, secure repositories, and restricted developer access.", "doc_link": "secure_development_policy.md"},
    {"id": "A.8.5", "section": "A.8 Technological", "title": "Secure authentication", "summary": "This control implements strong authentication mechanisms, such as multi-factor authentication, to verify user identities and prevent unauthorized access.", "doc_link": "access_control_policy.md"},
    {"id": "A.8.6", "section": "A.8 Technological", "title": "Capacity management", "summary": "This control ensures system capacity is managed to provide adequate performance and prevent disruptions. Measures include monitoring resource usage and planning for future needs.", "doc_link": "—"},
    {"id": "A.8.7", "section": "A.8 Technological", "title": "Protection against malware", "summary": "This control deploys measures like antivirus software, threat detection tools, and regular updates to protect systems from malware and malicious attacks.", "doc_link": "operations_security_policy.md"},
    {"id": "A.8.8", "section": "A.8 Technological", "title": "Management of technical vulnerabilities", "summary": "This control identifies, evaluates, and remediates technical vulnerabilities promptly to minimize security risks. Measures include vulnerability scanning and patch management.", "doc_link": "operations_security_policy.md"},
    {"id": "A.8.9", "section": "A.8 Technological", "title": "Configuration management", "summary": "This control ensures consistent management of system configurations to maintain security settings and prevent unauthorized changes.", "doc_link": "—"},
    {"id": "A.8.10", "section": "A.8 Technological", "title": "Information deletion", "summary": "Ensure information stored in systems, devices or other storage media is deleted when no longer required, to prevent unnecessary exposure of sensitive information and comply with legal, statutory, regulatory and contractual requirements for information deletion.", "doc_link": "data_retention_disposal_policy.md"},
    {"id": "A.8.11", "section": "A.8 Technological", "title": "Data masking", "summary": "Limit the exposure of sensitive data, including PII, by applying data masking during processing and display in line with the access control policy, other relevant policies and business requirements, and comply with applicable legislation.", "doc_link": "—"},
    {"id": "A.8.12", "section": "A.8 Technological", "title": "Data leakage prevention", "summary": "Apply data leakage prevention measures to systems, networks and devices that process, store or transmit sensitive information, to detect and prevent unauthorized disclosure and extraction of information by individuals or systems.", "doc_link": "—"},
    {"id": "A.8.13", "section": "A.8 Technological", "title": "Information backup", "summary": "This control ensures critical information is backed up regularly and securely to ensure its availability in case of incidents or disasters.", "doc_link": "backup_procedure.md"},
    {"id": "A.8.14", "section": "A.8 Technological", "title": "Redundancy of information processing facilities", "summary": "This control ensures redundancy is built into processing facilities to maintain availability and operations during system failures or emergencies.", "doc_link": "disaster_recovery_plan.md"},
    {"id": "A.8.15", "section": "A.8 Technological", "title": "Logging", "summary": "This control enables logging of activities within systems to support monitoring, incident detection, and forensic investigations.", "doc_link": "operations_security_policy.md"},
    {"id": "A.8.16", "section": "A.8 Technological", "title": "Monitoring activities", "summary": "This control ensures the ongoing monitoring of system activities to detect, respond to, and mitigate security threats.", "doc_link": "operations_security_policy.md"},
    {"id": "A.8.17", "section": "A.8 Technological", "title": "Clock synchronization", "summary": "This control ensures system clocks are synchronized to maintain accurate and consistent timestamps for logs and other critical processes.", "doc_link": "operations_security_policy.md"},
    {"id": "A.8.18", "section": "A.8 Technological", "title": "Use of privileged utility programs", "summary": "This control restricts and monitors the use of privileged utility programs to prevent misuse and unauthorized actions.", "doc_link": "—"},
    {"id": "A.8.19", "section": "A.8 Technological", "title": "Installation of software on operational systems", "summary": "This control ensures software installation on operational systems is managed securely to prevent vulnerabilities or unauthorized changes.", "doc_link": "operations_security_policy.md"},
    {"id": "A.8.20", "section": "A.8 Technological", "title": "Networks security", "summary": "This control ensures network security through firewalls, intrusion detection systems, and access controls to protect against unauthorized access and attacks.", "doc_link": "communication_security_policy.md"},
    {"id": "A.8.21", "section": "A.8 Technological", "title": "Security of network services", "summary": "This control ensures network services are protected to maintain confidentiality, integrity, and availability during use.", "doc_link": "communication_security_policy.md"},
    {"id": "A.8.22", "section": "A.8 Technological", "title": "Segregation of networks", "summary": "This control implements network segregation to limit the spread of threats and minimize the impact of potential breaches.", "doc_link": "communication_security_policy.md"},
    {"id": "A.8.23", "section": "A.8 Technological", "title": "Web filtering", "summary": "This control uses web filtering tools to block unauthorized or harmful content from being accessed over the internet.", "doc_link": "communication_security_policy.md"},
    {"id": "A.8.24", "section": "A.8 Technological", "title": "Use of cryptography", "summary": "Ensure rules for the effective use of cryptography, including cryptographic key management, are defined and implemented to protect the confidentiality, authenticity and integrity of information according to business and information security requirements, considering legal, statutory, regulatory and contractual requirements related to cryptography.", "doc_link": "cryptography_policy.md"},
    {"id": "A.8.25", "section": "A.8 Technological", "title": "Secure development life cycle", "summary": "This control integrates security into all stages of the development life cycle to ensure systems and applications are built securely.", "doc_link": "secure_development_policy.md"},
    {"id": "A.8.26", "section": "A.8 Technological", "title": "Application security requirements", "summary": "This control defines and enforces security requirements for applications to safeguard against vulnerabilities.", "doc_link": "secure_development_policy.md"},
    {"id": "A.8.27", "section": "A.8 Technological", "title": "Secure system architecture and engineering principles", "summary": "This control ensures secure design principles are adopted during the development of system architectures.", "doc_link": "secure_development_policy.md"},
    {"id": "A.8.28", "section": "A.8 Technological", "title": "Secure coding", "summary": "This control implements secure coding practices to minimize vulnerabilities in developed software.", "doc_link": "secure_development_policy.md"},
    {"id": "A.8.29", "section": "A.8 Technological", "title": "Security testing in development and acceptance", "summary": "Ensure security testing processes are defined and implemented in the development life cycle, to validate that information security requirements are met when applications or code are deployed to the production environment.", "doc_link": "secure_development_policy.md"},
    {"id": "A.8.30", "section": "A.8 Technological", "title": "Outsourced development", "summary": "This control ensures security risks are managed effectively when development is outsourced to third-party vendors.", "doc_link": "secure_development_policy.md"},
    {"id": "A.8.31", "section": "A.8 Technological", "title": "Separation of development, test and production environments", "summary": "This control ensures development, test, and production environments are segregated to prevent unintended interactions and unauthorized access.", "doc_link": "secure_development_policy.md"},
    {"id": "A.8.32", "section": "A.8 Technological", "title": "Change management", "summary": "This control ensures changes to systems are managed securely to minimize risks and maintain operational stability.", "doc_link": "change_management_policy.md"},
    {"id": "A.8.33", "section": "A.8 Technological", "title": "Test information", "summary": "Ensure test information is appropriately selected, protected and managed, so that testing remains relevant and operational information used for testing is not exposed.", "doc_link": "secure_development_policy.md"},
    {"id": "A.8.34", "section": "A.8 Technological", "title": "Protection of information systems during audit testing", "summary": "Ensure audit tests and other assurance activities involving operational systems are planned and agreed between the tester and appropriate management, to minimize their impact on operational systems and business processes.", "doc_link": "audit_policy.md"},
]

